// Verus specifications for the solve function
#[verifier::spec]
fn solve(n: i8) -> Vec<i8> {
    // Requires clause to specify the precondition
    // n must be a non-negative integer
    #[requires(n >= 0)]
    // Ensures clause to specify the postcondition
    // The result vector must contain two elements: min_days_off and max_days_off
    #[ensures(result.len() == 2)]
    #[ensures(result[0] == 2 * (n / 7) + std::cmp::max(0, n % 7 - 5))]
    #[ensures(result[1] == 2 * (n / 7) + std::cmp::min(2, n % 7))]
    let result = {
        // Calculate the number of complete weeks and the remaining days
        let complete_weeks = n / 7;
        let remaining_days = n % 7;

        // Calculate the minimum days off
        let min_days_off = 2 * complete_weeks + std::cmp::max(0, remaining_days - 5);
        
        // Calculate the maximum days off
        let max_days_off = 2 * complete_weeks + std::cmp::min(2, remaining_days);

        // Return the result as a vector
        vec![min_days_off, max_days_off]
    };

    result
}

